import base64, gzip, subprocess

print('>>> 1. Updating backend/database.py...')
with open('/var/www/goverment-ai/backend/database.py', 'wb') as f:
    f.write(gzip.decompress(base64.b64decode('')))

print('>>> 2. Updating backend/models.py...')
with open('/var/www/goverment-ai/backend/models.py', 'wb') as f:
    f.write(gzip.decompress(base64.b64decode('')))

print('>>> 3. Updating backend/main.py...')
with open('/var/www/goverment-ai/backend/main.py', 'wb') as f:
    f.write(gzip.decompress(base64.b64decode('')))

print('>>> 4. Restarting goverment-ai systemd service...')
subprocess.run(['systemctl', 'restart', 'goverment-ai'], check=True)
print('>>> SUCCESS! Server updated and restarted with streaming fix & instant greetings!')
